/* Locale paths (Inception Report 3.1): every page lives under /ar/, /en/ and /es/. The locale copies are generated by build-locales.mjs,
   carry <base href="../"> so assets resolve from the root, and set window.LOCALE. Root pages only forward to the preferred locale. */
(() => {
  const m = location.pathname.match(/\/(ar|en|es)\/[^/]*$/);
  const L = m ? m[1] : null;
  window.LOCALE = L;
  /* page links built by scripts resolve against <base>; this keeps them inside the current locale */
  window.LURL = u => (L && /^[\w-]+\.html/.test(u)) ? L + '/' + u : u;
  window.LOCALE_NAV = L ? (l => { const p = location.pathname.replace(/\/(ar|en|es)\/([^/]*)$/, '/' + l + '/$2'); location.href = p + location.search + location.hash; }) : null;
  if (!L) {
    if (location.protocol === 'file:') return;
    const file = location.pathname.split('/').pop() || 'index.html';
    if (!/\.html$/.test(file) && file !== '') return;
    let saved = null; try { saved = localStorage.getItem('se-lang'); } catch {}
    const to = ['ar', 'en', 'es'].includes(saved) ? saved : 'ar';
    location.replace(to + '/' + (file || 'index.html') + location.search + location.hash);
    return;
  }
  try { localStorage.setItem('se-lang', L); } catch {}
  document.addEventListener('click', e => {
    const a = e.target.closest('a[href]'); if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || a.target === '_blank') return;
    const raw = a.getAttribute('href'); if (!raw) return;
    if (raw.startsWith('#')) { e.preventDefault(); if (raw.length > 1) { const el = document.getElementById(raw.slice(1)); if (el) el.scrollIntoView(); } history.replaceState(null, '', location.pathname + location.search + raw); return; }
    if (/^(https?:|mailto:|tel:|javascript:)/.test(raw) || raw.startsWith(L + '/') || !/^[\w-]+\.html/.test(raw)) return;
    e.preventDefault(); location.href = L + '/' + raw;
  }, true);
})();
